    for i in seq(0, n):
        # Compute L entries (below diagonal)
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U entries (on and above diagonal)
        for j in seq(i, n):
            w = A[i, j]
            for k in seq(0, i):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w

