        # We use a per-iteration temporary so that we can safely
        # parallelize across columns later without races.
        for j in seq(i, n):
            wu: DATA_TYPE
            wu = A[i, j]
            for k in seq(0, i):
                wu = wu - A[i, k] * A[k, j]
            A[i, j] = wu

    # Forward substitution to solve L * y = b.
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # Backward substitution to solve U * x = y.
    # Exo loops are forward-only, so we iterate i upward and
    # map to the original index i0 = n - 1 - i.
    for i in seq(0, n):
