from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


@proc
def kernel_ludcmp(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # Temporary scalars used across the algorithm
    w: DATA_TYPE
    alpha: DATA_TYPE

    # LU decomposition in-place on A (Doolittle method).
    # L is stored in the strictly lower-triangular part of A (unit diagonal),
    # U is stored in the upper-triangular part including the diagonal.
    for i in seq(0, n):
        # Compute L entries for row i (below diagonal).
        # Each A[i, j] with j < i becomes L[i, j].
        for j in seq(0, i):
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U entries for row i (on and above the diagonal).
        # Original PolyBench code uses:
        #   for j in seq(i, n):
        #       w = A[i, j]
        #       for k in seq(0, i):
        #           w = w - A[i, k] * A[k, j]
        #       A[i, j] = w
        #
        # Here we use an equivalent outer-product style update:
        #   for k in seq(0, i):
        #       alpha = A[i, k]
        #       for j in seq(i, n):
        #           A[i, j] = A[i, j] - alpha * A[k, j]
        #
        # This improves temporal locality on A[i, k] and A[k, j]:
        #   - A[i, k] is loaded once per (i, k) pair and reused across all j.
        #   - A[k, j] is streamed across j for each fixed k.
        # The mathematical result is identical:
        #   A[i, j]_final = A[i, j]_initial - sum_{k=0}^{i-1} A[i, k] * A[k, j]
        for k in seq(0, i):
            alpha = A[i, k]
            for j in seq(i, n):
                A[i, j] = A[i, j] - alpha * A[k, j]

    # Forward substitution to solve L * y = b.
    # L has implicit unit diagonal, stored in the strictly lower part of A.
    for i in seq(0, n):
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # Backward substitution to solve U * x = y.
    # U is the upper-triangular part of A including the diagonal.
    #
    # Original C loop (with decreasing i):
    #   for (i = n-1; i >= 0; i--) {
    #       w = y[i];
    #       for (j = i+1; j < n; j++)
    #           w -= A[i][j] * x[j];
    #       x[i] = w / A[i][i];
    #   }
    #
    # We implement the same computation using an increasing i
    # and explicit index transformation i0 = n - 1 - i.
    for i in seq(0, n):
        w = y[n - 1 - i]
        for j in seq(n - i, n):
            w = w - A[n - 1 - i, j] * x[j]
        x[n - 1 - i] = w / A[n - 1 - i, n - 1 - i]


# Apply a light-weight canonicalization pass. This uses Exo's scheduling
# infrastructure but does not change the algorithmic structure above.
kernel_ludcmp = simplify(kernel_ludcmp)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_ludcmp(/*ctxt=*/NULL, n,
                (DATA_TYPE*)POLYBENCH_ARRAY(A),
                (DATA_TYPE*)POLYBENCH_ARRAY(b),
                (DATA_TYPE*)POLYBENCH_ARRAY(x),
                (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
