EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


@proc
def kernel_ludcmp_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    # LU decomposition: in-place Doolittle factorization of A into L and U.
    for i in seq(0, n):
        # Compute L entries (strictly below diagonal).
        for j in seq(0, i):
            # Local accumulator for A[i, j] update.
            w: DATA_TYPE
            w = A[i, j]
            for k in seq(0, j):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w / A[j, j]

        # Compute U entries (on and above diagonal).
        for j in seq(i, n):
            # Each column update has its own local accumulator.
            w: DATA_TYPE
            w = A[i, j]
            for k in seq(0, i):
                w = w - A[i, k] * A[k, j]
            A[i, j] = w

    # Forward substitution: solve L * y = b.
    for i in seq(0, n):
        w: DATA_TYPE
        w = b[i]
        for j in seq(0, i):
            w = w - A[i, j] * y[j]
        y[i] = w

    # Backward substitution: solve U * x = y.
    # Original C loop:
    # for (i = n-1; i >= 0; i--) {
    #   w = y[i];
    #   for (j = i+1; j < n; j++)
    #       w -= A[i][j] * x[j];
    #   x[i] = w / A[i][i];
    # }
    #
    # Rewritten to forward-iterating form over i with equivalent semantics.
    for i in seq(0, n):
        # Map forward index i to original backward index i0 = n - 1 - i.
        w: DATA_TYPE
        w = y[n - 1 - i]
        for j in seq(n - i, n):
            w = w - A[n - 1 - i, j] * x[j]
        x[n - 1 - i] = w / A[n - 1 - i, n - 1 - i]


# ---------------------------------------------------------------------------
# Scheduling: improve cache locality and expose parallelism in the U update.
# ---------------------------------------------------------------------------

# Start from the mathematical specification.
kernel_ludcmp = kernel_ludcmp_base

# 1) In the upper-triangular update (U), shift the j-loop to start at zero.
#    This keeps the iteration space equivalent but makes it easier to tile.
i_outer = kernel_ludcmp.find_loop("i")  # first 'i' loop: LU decomposition
j_u = i_outer.body().find("for j in _:_ #1")  # second j-loop inside the LU body
kernel_ludcmp = shift_loop(kernel_ludcmp, j_u, "0")

# 2) Tile the shifted U j-loop along the column dimension.
#    This improves spatial locality in A's row-major layout and amortizes
#    loop overhead within each tile. T_J is a tunable tile size.
T_J = 32  # good default for modern L1/L2 caches; can be retuned per architecture

i_outer = kernel_ludcmp.find_loop("i")  # re-acquire after transformation
j_u = i_outer.body().find("for j in _:_ #1")
kernel_ludcmp = divide_loop(kernel_ludcmp, j_u, T_J, ["jo", "ji"], tail="guard")

# 3) Parallelize the outer tile loop over columns.
#    For a fixed row i, different tiles of j are independent: each iteration
#    updates a distinct A[i, j] and uses a tile-local accumulator w.
jo_loop = kernel_ludcmp.find_loop("jo")
kernel_ludcmp = parallelize_loop(kernel_ludcmp, jo_loop)

# 4) Clean up algebra and control that became slightly more complex after
#    shifting and tiling.
kernel_ludcmp = simplify(kernel_ludcmp)

# Finally, rename the optimized kernel to the name expected by the C driver.
kernel_ludcmp = rename(kernel_ludcmp, "kernel_ludcmp")
